import{_ as t,o,c as s,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Plan — FR 3.2.4: Reset Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-4-reset-password/plan.md","filePath":"feature/srs/01-authentication/3-2-4-reset-password/plan.md"}'),d={name:"feature/srs/01-authentication/3-2-4-reset-password/plan.md"};function r(i,e,n,c,l,u){return o(),s("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-4-reset-password" tabindex="-1">Plan — FR 3.2.4: Reset Password <a class="header-anchor" href="#plan-—-fr-3-2-4-reset-password" aria-label="Permalink to &quot;Plan — FR 3.2.4: Reset Password&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Anti-enumeration password reset token issuance (<code>POST /api/v1/auth/forgot-password</code>), single-use Redis token consumption (<code>POST /api/v1/auth/reset-password</code>), BCrypt hashing (<code>BR-02</code>), and prior session invalidation (<code>BR-08</code>).</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (public routes <code>/api/v1/auth/forgot-password</code>, <code>/api/v1/auth/reset-password</code>), <code>RateLimitGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/AuthController.java</code> (<code>forgotPassword</code>, <code>resetPassword</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/AuthServiceImpl.java</code> (<code>forgotPassword</code>, <code>resetPassword</code>), <code>service/mail/MailService.java</code></td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>ForgotPasswordRequest</code>, <code>ResetPasswordRequest</code>, <code>ErrorCode</code> (<code>RESET_TOKEN_INVALID</code>, <code>RESET_TOKEN_USED</code>, <code>VALIDATION_ERROR</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UserRepository.java</code>, <code>UserRefreshTokenRepository.java</code>, <code>AuditLogRepository.java</code>, <code>StringRedisTemplate</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/auth/ForgotPasswordPage.tsx</code>, <code>src/pages/auth/ResetPasswordPage.tsx</code>, <code>src/components/auth/{PasswordInput,PasswordStrengthMeter}.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>app/(auth)/forgot-password.tsx</code>, <code>app/(auth)/reset-password.tsx</code>, <code>src/services/authService.ts</code></td></tr></tbody></table><h2 id="_2-architectural-mechanism-redis-reverse-index-design" tabindex="-1">2. Architectural Mechanism &amp; Redis Reverse-Index Design <a class="header-anchor" href="#_2-architectural-mechanism-redis-reverse-index-design" aria-label="Permalink to &quot;2. Architectural Mechanism &amp; Redis Reverse-Index Design&quot;">​</a></h2><ul><li><strong>Email Link Token Mechanism:</strong> Uses a high-entropy single-use reset token sent via email link (<code>/reset-password?token=&lt;token&gt;</code>) backed by dual Redis keys with TTL = <code>appProperties.passwordResetTtlSeconds</code> (10 minutes): <ul><li><code>pwd:reset:{token}</code> -&gt; <code>userId</code> (primary lookup consumed atomically during <code>resetPassword</code>).</li><li><code>pwd:reset:user:{userId}</code> -&gt; <code>token</code> (reverse index allowing a subsequent <code>forgot-password</code> request to immediately delete any previously issued <code>oldToken</code> rather than leaving multiple active reset tokens).</li></ul></li><li><strong>Session Invalidation (<code>BR-08</code>):</strong> Setting <code>users.last_password_change = Instant.now()</code> (and revoking active <code>user_refresh_tokens</code>) immediately invalidates all refresh tokens issued prior to the password reset.</li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Request Reset (<code>POST /api/v1/auth/forgot-password</code>):</strong><ul><li>Validates email format (<code>400 VALIDATION_ERROR</code> if malformed) and normalizes <code>email</code> (<code>lowercase + trim</code>).</li><li>Looks up <code>User</code>: if absent or non-active, returns <code>200 OK</code> silently without sending email (preventing email enumeration and mail spam).</li><li>If <code>User</code> exists: reads <code>pwd:reset:user:{userId}</code>, deletes <code>pwd:reset:{oldToken}</code> if present, generates new token, stores both <code>pwd:reset:{token}</code> and <code>pwd:reset:user:{userId}</code> with matching TTL, dispatches reset link email, and returns <code>200 OK</code>.</li></ul></li><li><strong>Confirm New Password (<code>POST /api/v1/auth/reset-password</code>):</strong><ul><li>Validates <code>newPassword</code> against <code>BR-02</code> (min 8 chars, &gt;= 1 digit).</li><li>Resolves <code>userId</code> from <code>pwd:reset:{token}</code> (<code>400 RESET_TOKEN_INVALID</code> if missing/expired) and atomically deletes <code>pwd:reset:{token}</code> (<code>400 RESET_TOKEN_USED</code> if a concurrent request consumed it first) + deletes <code>pwd:reset:user:{userId}</code>.</li><li>Updates <code>user.passwordHash</code> (BCrypt cost 12), stamps <code>user.lastPasswordChange = now</code>, writes <code>AuditLog(PASSWORD_RESET)</code>, and returns <code>200 OK</code>.</li></ul></li></ol><h2 id="_4-security-concurrency-guards" tabindex="-1">4. Security &amp; Concurrency Guards <a class="header-anchor" href="#_4-security-concurrency-guards" aria-label="Permalink to &quot;4. Security &amp; Concurrency Guards&quot;">​</a></h2><ul><li><strong>Zero Account Enumeration:</strong> Both registered and unregistered emails receive identical <code>200 ApiResponse&lt;Void&gt;</code> payloads on <code>/forgot-password</code>.</li><li><strong>Single-Active-Token Guarantee:</strong> Requesting <code>/forgot-password</code> twice immediately invalidates the first token via the <code>pwd:reset:user:{userId}</code> reverse index.</li><li><strong>OAuth-Only Account Recovery:</strong> Allows an OAuth-provisioned user (<code>passwordHash == null</code>) to establish a password via email verification proof while keeping their Google link intact.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.4</code> — Reset Password</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/forgot-password · POST /api/v1/auth/reset-password</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl, MailService</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code> (<code>password_hash</code>, <code>last_password_change</code>), <code>audit_logs</code>; Redis <code>pwd:reset:{token}</code>, <code>pwd:reset:user:{userId}</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-02, BR-03, BR-04, BR-08</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 VALIDATION_ERROR</code> / <code>RESET_TOKEN_INVALID</code> / <code>RESET_TOKEN_USED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/auth/ForgotPasswordPage.tsx</code>, <code>src/pages/auth/ResetPasswordPage.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>app/(auth)/forgot-password.tsx</code>, <code>app/(auth)/reset-password.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>auth.forgotPassword.* / auth.resetPassword.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',15)])])}const h=t(d,[["render",r]]);export{p as __pageData,h as default};
